import { chromium } from 'playwright';import fs from 'fs';
const BASE='https://www.statesideqm.com',THEME='158900125851',ROOT='/collections/state-guard-series',OUT='sep18-final-load-discovery';fs.mkdirSync(OUT,{recursive:true});
const b=await chromium.launch({headless:true});const c=await b.newContext({viewport:{width:1440,height:1000}});const p=await c.newPage();p.setDefaultNavigationTimeout(70000);
async function nav(route){for(let a=1;a<=4;a++){const u=new URL(route,BASE);u.searchParams.set('preview_theme_id',THEME);const r=await p.goto(u.href,{waitUntil:'domcontentloaded',timeout:70000}).catch(()=>null);const s=r?.status()||0;if(![429,500,503].includes(s)){await p.waitForLoadState('load',{timeout:16000}).catch(()=>{});await p.waitForTimeout(1000);return r}await p.waitForTimeout(a*5000)}return null}
function okTheme(){return p.evaluate(()=>String(window.Shopify?.theme?.id||''))}
async function discover(route){const r=await nav(route);if(r?.status()!==200)throw new Error('discovery http '+r?.status()+' '+route);if(await okTheme()!==THEME)throw new Error('wrong theme '+route);return p.evaluate(({base})=>{const main=document.getElementById('MainContent')||document.body,vis=e=>{const s=getComputedStyle(e),r=e.getBoundingClientRect();return s.display!=='none'&&s.visibility!=='hidden'&&!e.hidden&&r.width>8&&r.height>20},out=[];for(const a of main.querySelectorAll('a[href]')){if(!vis(a))continue;let u;try{u=new URL(a.href,base)}catch{continue}if(u.origin!==new URL(base).origin||!/^\/(collections|pages)\//.test(u.pathname)||/\/products\//.test(u.pathname))continue;u.searchParams.delete('preview_theme_id');u.hash='';const label=(a.getAttribute('aria-label')||a.textContent||a.querySelector('img')?.alt||'').replace(/\s+/g,' ').trim();if(!label)continue;const r=a.getBoundingClientRect(),card=!!(a.querySelector('img,svg')||a.closest('[class*="card"],[class*="grid"],[data-sq-state-guard-root]')||r.width>140||r.height>50);if(!card)continue;out.push({label:label.slice(0,220),route:u.pathname+u.search})}const seen=new Set();return out.filter(x=>!seen.has(x.route)&&(seen.add(x.route),true))},{base:BASE})}
const home=await discover('/');await p.waitForTimeout(2500);const sg=await discover(ROOT);const all=[...home.map(x=>({...x,group:'homepage'})),...sg.map(x=>({...x,group:'state-guard-root'}))];const matrix={include:all.map((x,i)=>({key:String(i+1).padStart(2,'0'),label:x.label,route:x.route,group:x.group}))};const theme=await p.evaluate(()=>({id:String(window.Shopify?.theme?.id||''),name:String(window.Shopify?.theme?.name||'')}));fs.writeFileSync(OUT+'/discovery.json',JSON.stringify({generatedAt:new Date().toISOString(),theme,homeCount:home.length,stateGuardRootCount:sg.length,total:all.length,home,sg,matrix},null,2));fs.appendFileSync(process.env.GITHUB_OUTPUT,'matrix='+JSON.stringify(matrix)+'\n');fs.appendFileSync(process.env.GITHUB_OUTPUT,'home_count='+home.length+'\n');fs.appendFileSync(process.env.GITHUB_OUTPUT,'sg_count='+sg.length+'\n');fs.appendFileSync(process.env.GITHUB_OUTPUT,'total='+all.length+'\n');console.log('FINALDISCOVERY',JSON.stringify({theme,homeCount:home.length,stateGuardRootCount:sg.length,total:all.length}));await c.close();await b.close();